import numpy as np
def equation(t, x, v, params):
    return params[0] + params[1]*x + params[2]*v + params[3]*x**3 + params[4]*v*np.abs(v) + params[5]*np.cos(params[6]*t) + params[7]*np.sin(params[6]*t)

def polybasis(deg):
    cols=[];names=[]
    for i in range(deg+1):
        for j in range(deg+1-i):
            cols.append(x**i*v**j); names.append(f"x^{i}v^{j}")
    return cols,names
cols,names=polybasis(3)
best=None
for w in np.linspace(0.25,0.4,301):
    A=np.column_stack(cols+[np.cos(w*t),np.sin(w*t)])
